            "scope": "Independent branching/merging DAG longest-path ranks and lexical lanes; centred uniform cards under page budgets. Native SVG/readback reconstructs geometry, checks connector/arrow extents and measures fixed-font label fit.",
            "checks": [
              {
                "file": "verification.json",
                "format": "json",
