                "expected": "dag-longest-path/1"
              },
              {
                "file": "verification.json",
                "format": "json",
                "pointer": "/native/layout/rankCount",
                "expected": 4
              },
              {
                "file": "verification.json",
                "format": "json",
                "pointer": "/native/layout/laneCounts",
                "expected": [
                  1,
                  2,
                  1,
                  1
                ]
              },
              {
                "file": "verification.json",
                "format": "json",
                "pointer": "/native/layout/ranks",
                "expected": {
                  "input": 0,
                  "model": 1,
                  "result": 3,
                  "simulate": 1,
                  "validate": 2
                }
              },
              {
                "file": "verification.json",
                "format": "json",
                "pointer": "/native/layout/requiredSize/0",
                "expected": 150.6,
                "absolute": 1e-10,
                "relative": 1e-10
              },
              {
                "file": "verification.json",
                "format": "json",
                "pointer": "/native/layout/requiredSize/1",
                "expected": 36.8,
                "absolute": 1e-10,
                "relative": 1e-10
              }
            ]
          }
        ]
      },
      "completion": {
        "scope": "Strengthening of existing blockDiagram and flowDiagram: label input boundary (blank and Unicode line-separator labels rejected before launch; flow label faults located at the authored box) and an unsupported Inkscape runtime now fails with UNSUPPORTED_RUNTIME before query/export instead of a misleading VERIFICATION_FAILED. No new operation, native option or format; retained receipts and the 1.4.4 native qualification are not re-run or extended.",
        "review": [
          "verification/2026-10-10-inkscape-diagrams.md",
          "verification/2026-10-10-inkscape-flows.md",
          "verification/2026-10-24-inkscape-allocation.md"
        ]
      }
    }
  }
}
